#!/usr/bin/env python3
"""Run TSP-3: source-timestamp provenance vs ordinary GStreamer PTS."""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from navmin.diagnostics.timestamp_transport import (
    TimestampTransportProofError,
    run_timestamp_provenance_proof,
    write_timestamp_provenance_json,
)


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description=(
            "Determine whether decoded appsink PTS presence can distinguish an explicit "
            "source timestamp from a timestamp generated by GStreamer itself."
        )
    )
    parser.add_argument("--port", type=int, default=18_928, help="first localhost UDP port")
    parser.add_argument("--output-json", type=Path)
    return parser


def main() -> int:
    args = _parser().parse_args()
    try:
        result = run_timestamp_provenance_proof(base_port=args.port)
    except (TimestampTransportProofError, ValueError) as exc:
        print(f"TIMESTAMP PROVENANCE PROOF: BLOCKED — {exc}", file=sys.stderr)
        return 2

    print(f"TIMESTAMP PROVENANCE PROOF: {result.status}")
    print(f"GStreamer: {result.gstreamer_version}")
    for variant in result.variants:
        print(f"VARIANT {variant.name}")
        print(f"  source timestamp present: {variant.source_timestamp_present}")
        print(f"  appsrc do-timestamp: {variant.appsrc_do_timestamp}")
        print(f"  input PTS ns: {list(variant.input_pts_ns)}")
        print(f"  output PTS ns: {list(variant.output_pts_ns)}")
        print(f"  received all: {variant.received_all_frames}")
        print(f"  output PTS available: {variant.output_pts_available}")
        print(f"  output monotonic: {variant.output_monotonic}")
        print(f"  output strictly increasing: {variant.output_strictly_increasing}")
    print(f"PTS presence proves source provenance: {result.pts_presence_is_provenance}")
    print(f"Conclusion: {result.conclusion}")
    if args.output_json is not None:
        write_timestamp_provenance_json(result, args.output_json)
        print(f"JSON: {args.output_json}")
    return 0 if result.passed else 1


if __name__ == "__main__":
    raise SystemExit(main())
